const players = context.use(PLAYER_VIEWS);
const view = players.create({ binding, adapters: {
  input: players.controller(controller, 'owned'),
  camera: players.camera(camera), // borrowed from local views
  hud: players.hud(hud, 'owned'),
  appearance: myAppearanceAdapter,
} });
view.bind({ ...view.binding, targetId: nextEntity });
view.configure({ ...view.adapters, appearance: anotherAppearanceAdapter });
view.dispose();
